) -> Result<vb_core::WorkflowDigest, String> {
    let bytes = postcard::to_allocvec(&workflow.to_parts())
        .map_err(|e| format!("serialize compiled workflow parts: {e}"))?;
    Ok(vb_core::WorkflowDigest::from_bytes(
        blake3::hash(&bytes).into(),
    ))
}

